"C:\\windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$project = (Resolve-Path -LiteralPath '"'.\\saved_configs\\CampusNetwork_04').Path; "'$targets = @(
@{N='"'HQ_MKT_AP01'; I=@('GE1/0/0','GE1/0/2')},
@{N='Core_SW_01'; I=@('GE1/0/3','GE1/0/8','GE1/0/9')},
@{N='Core_SW_02'; I=@('GE1/0/3','GE1/0/8','GE1/0/9')},
@{N='ChinaUnicom_SW'; I=@('GE1/0/1','GE1/0/3')}
); foreach("'$t in $targets){ Write-Output "[$($t.N)]"; $p=Join-Path (Join-Path $project $t.N) '"'display_interface.txt'; "'$lines=Get-Content -LiteralPath $p; foreach($iface in $t.I){ $m=Select-String -InputObject $lines -Pattern "''^$([regex]::Escape($iface)) current state"; if($m){ $s=$m.LineNumber-1; $e=[Math]::Min($s+32,$lines.Count-1); $lines[$s..$e] } } }'

